    deepExplanation: "Step 1 — Basic cache.\n\nWITHOUT BUILT-IN / CORE:\n```ts\nfunction createSimpleCache<T, R>() {\n  const keys: T[] = [];\n  const values: R[] = [];\n\n  return {\n    get(key: T): R | undefined {\n      for (let i = 0; i < keys.length; i++) {\n        if (keys[i] === key) return values[i];\n      }\n      return undefined;\n    },\n\n    set(key: T, value: R): void {\n      for (let i = 0; i < keys.length; i++) {\n        if (keys[i] === key) {\n          values[i] = value;\n          return;\n        }\n      }\n\n      keys.push(key);\n      values.push(value);\n    },\n  };\n}\n```\n\nWITH BUILT-IN:\n```ts\nfunction memoize<T extends string | number, R>(\n  fn: (key: T) => R,\n): (key: T) => R {\n  const cache = new Map<T, R>();\n\n  return (key: T): R => {\n    if (cache.has(key)) return cache.get(key)!;\n\n    const result = fn(key);\n    cache.set(key, result);\n    return result;\n  };\n}\n```\n\nStep 2 — Example:\nFirst call memoized(5) → compute.\nSecond call memoized(5) → return cached value.\n\nStep 3 — Production note:\nA real cache needs a policy such as TTL or LRU so it does not grow forever.",
